import { API_URL } from 'proton-mail/config';

const LinksURLs: { [key: string]: { href: string; messageID: string; class?: string; style?: string } } = {};
const ImageURLs: {
    [key: string]: {
        src: string;
        'proton-src'?: string;
        class?: string;
        id?: string;
        'data-embedded-img'?: string;
        style?: string;
        messageID: string;
    };
